rate-fee .student-id{font-size:11px;color:var(--muted)}.legacy-generate-fee .modal-list{max-height:420px;overflow:auto;border:1px solid var(--line);border-radius:5px}.legacy-generate-fee .modal-list label{display:block;padding:9px 11px;margin:0;border-bottom:1px solid #eef1f4;font-weight:500}.legacy-generate-fee .modal-list label:last-child{border-bottom:0}@media(max-width:991px){.legacy-generate-fee .criteria{grid-template-columns:repeat(2,minmax(150px,1fr))}.legacy-generate-fee .fee-row{grid-template-columns:1fr 1fr}.legacy-generate-fee .fee-row .remove-fee{justify-self:end}}@media(max-width:600px){.legacy-generate-fee .criteria,.legacy-generate-fee .fee-row{grid-template-columns:1fr}.legacy-generate-fee .student-toolbar,.legacy-generate-fee .action-bar,.legacy-generate-fee .action-buttons{align-items:stretch;flex-direction:column}.legacy-generate-fee .student-search{max-width:none}}
</style>
