  <div class="box box-primary"><div class="box-header"><h3 class="box-title"><span class="step">1</span>Billing criteria <small class="text-muted">Session <?php echo html_escape($current_session_name); ?></small></h3></div><div class="box-body"><div class="criteria">
   <div><label>Class *</label><select id="fee_class" class="form-control"><option value="">Select class</option><?php foreach($classlist as $class){ ?><option value="<?php echo (int)$class['id']; ?>"><?php echo html_escape($class['class']); ?></option><?php } ?></select></div>
