   <div class="table-responsive"><table class="table table-striped table-bordered" id="student_table"><thead><tr><th width="35"></th><th>Admission No.</th><th>Student</th><th>Class / Section</th><th class="text-right">Monthly Fee</th><th>Current Month Status</th></tr></thead><tbody></tbody></table></div>
   <div class="action-bar"><div class="action-note"><i class="fa fa-lock"></i> Generated amounts are immutable. Due dates change only for unique, unpaid and undiscounted rows.</div><div class="action-buttons"><?php if($this->rbac->hasPrivilege('fees_master','can_edit')){ ?><button id="change_due_date" class="btn btn-warning" type="button"><i class="fa fa-calendar"></i> Change Due Date</button><?php } ?><?php if($this->rbac->hasPrivilege('fees_master','can_add')){ ?><button id="generate_fees" class="btn btn-success" type="button"><i class="fa fa-bolt"></i> Generate Selected Fees</button><?php } ?></div></div>
  </div></div>
 </section>
