<div class="modal fade" id="fee_students_modal" tabindex="-1"><div class="modal-dialog"><div class="modal-content"><div class="modal-header"><button class="close" data-dismiss="modal">&times;</button><h4 class="modal-title">Select students for <span id="picker_fee_name"></span></h4></div><div class="modal-body"><div class="checkbox"><label><input id="picker_all" type="checkbox"> Select all included students</label></div><input id="picker_search" class="form-control" placeholder="Search students" style="margin-bottom:10px"><div id="picker_list" class="modal-list"></div></div><div class="modal-footer"><button class="btn btn-default" data-dismiss="modal">Cancel</button><button id="save_picker" class="btn btn-primary" type="button">Apply Students</button></div></div></div></div>

<script>
(function($){'use strict';
var base=<?php echo json_encode(base_url()); ?>,token=<?php echo json_encode($operation_token); ?>,types=<?php echo json_encode(array_values($feetypeList)); ?>,currency=<?php echo json_encode($currency_symbol); ?>;
var students={},rowNo=0,pickerRow=null,pickerSelection=[],busy=false;
function esc(v){return $('<div>').text(v==null?'':v).html()}function money(v){v=parseFloat(v);return(isNaN(v)?0:v).toFixed(2)}
function billing(){var p=($('#fee_month').val()||'').split('-');return{class_id:+$('#fee_class').val()||0,section_id:+$('#fee_section').val()||0,year:+p[0]||0,month:+p[1]||0,due_date:$('#fee_due_date').val()}}
function includedIds(){var a=[];$.each(students,function(id,s){if(s.selected&&s.eligible)a.push(+id)});return a}
function typeOptions(id){var h='<option value="">Select fee type</option>';$.each(types,function(_,x){h+='<option value="'+(+x.id)+'" data-code="'+esc(x.code)+'"'+(String(x.id)===String(id)?' selected':'')+'>'+esc(x.type)+'</option>'});return h}
function addRow(id,amount){rowNo++;var r=$('<div class="fee-row" data-row="'+rowNo+'"><select class="form-control fee-type">'+typeOptions(id)+'</select><input class="form-control fee-amount" type="number" min="0" step="0.01" placeholder="Amount" value="'+esc(amount||'')+'"><button class="btn btn-default student-picker" type="button"><i class="fa fa-users"></i> <span>All included students</span></button><button class="btn btn-danger remove-fee" type="button"><i class="fa fa-minus"></i></button></div>');r.data('targets',null);$('#fee_rows').append(r);amountState(r)}
function amountState(r){var code=String(r.find('.fee-type option:selected').data('code')||'').toLowerCase(),auto=code==='tuition'||code==='admission';r.find('.fee-amount').prop('disabled',auto).attr('placeholder',auto?'Student profile amount':'Common amount')}
function effectiveTargets(r){var allowed=includedIds(),set=r.data('targets');if(set===null||set===undefined)return allowed;return $.grep(set,function(id){return allowed.indexOf(+id)!==-1})}
function refreshPickerLabel(r){var n=effectiveTargets(r).length,total=includedIds().length;r.find('.student-picker span').text(n===total?'All included students':n+' student(s) selected')}
function refreshAllLabels(){$('#fee_rows .fee-row').each(function(){refreshPickerLabel($(this))})}
function loadSections(){var s=$('#fee_section').html('<option value="">All sections</option>'),id=$('#fee_class').val();if(!id)return;$.getJSON(base+'sections/getByClass',{class_id:id},function(a){$.each(a||[],function(_,x){s.append($('<option>').val(x.section_id||x.id).text(x.section))})})}
function loadStudents(){var p=billing();if(!p.class_id||!p.year||!p.month||!p.due_date)return message('danger','Select class, fee month and due date.');setBusy(1);$.post(base+'admin/feemaster/loadGenerationStudents',{payload:JSON.stringify(p)},null,'json').done(function(r){students={};$.each(r.students||[],function(_,s){s.selected=!!s.eligible;students[String(s.student_session_id)]=s});render();$('#student_box').show();refreshAllLabels();message('success',(r.students||[]).length+' active student(s) loaded by student/session ID.')}).fail(error).always(function(){setBusy(0)})}
function status(s){if(!s.eligible)return'<span class="status locked">Not eligible</span>';if(!s.fees||!s.fees.length)return'<span class="status new">Not generated</span>';var h='';$.each(s.fees,function(_,f){var locked=f.locked||f.duplicate;h+='<span class="status '+(locked?'locked':'open')+'"><i class="fa fa-lock"></i> '+esc(f.type)+' '+esc(currency)+money(f.amount)+(locked?' protected':' amount locked')+'</span>'});return h}
function render(){var q=$.trim($('#student_search').val()).toLowerCase(),b=$('#student_table tbody').empty(),shown=0,eligible=0,selected=0;$.each(students,function(id,s){if(s.eligible)eligible++;if(s.selected)selected++;var name=$.trim([s.firstname,s.middlename,s.lastname].join(' ')),hay=(s.admission_no+' '+name+' '+s.class+' '+s.section).toLowerCase();if(q&&hay.indexOf(q)<0)return;shown++;b.append('<tr data-id="'+(+id)+'"><td><input class="student-check" type="checkbox"'+(s.selected?' checked':'')+(s.eligible?'':' disabled')+'></td><td>'+esc(s.admission_no)+'<div class="student-id">Student ID '+(+s.student_id)+' / Session ID '+(+id)+'</div></td><td><strong>'+esc(name)+'</strong></td><td>'+esc(s.class)+' / '+esc(s.section)+'</td><td class="text-right">'+esc(currency)+money(s.monthly_fee)+'</td><td>'+status(s)+'</td></tr>')});if(!shown)b.append('<tr><td colspan="6" class="text-center text-muted">No students found.</td></tr>');$('#select_all').prop('checked',eligible>0&&eligible===selected);refreshAllLabels()}
function openPicker(r){if(!Object.keys(students).length)return message('warning','Load students first.');pickerRow=r;pickerSelection=effectiveTargets(r);var name=r.find('.fee-type option:selected').text();$('#picker_fee_name').text(name==='Select fee type'?'this fee row':name);$('#picker_search').val('');renderPicker(pickerSelection,'');$('#fee_students_modal').modal('show')}
function renderPicker(targets,q){var h='',allowed=includedIds();$.each(students,function(id,s){if(allowed.indexOf(+id)===-1)return;var name=$.trim([s.firstname,s.middlename,s.lastname].join(' ')),hay=(s.admission_no+' '+name).toLowerCase();if(q&&hay.indexOf(q)<0)return;h+='<label><input class="picker-check" type="checkbox" value="'+(+id)+'"'+(targets.indexOf(+id)!==-1?' checked':'')+'> <strong>'+esc(s.admission_no)+'</strong> - '+esc(name)+'</label>'});$('#picker_list').html(h||'<div class="text-muted text-center" style="padding:15px">No included students match.</div>');$('#picker_all').prop('checked',allowed.length>0&&$('.picker-check:checked').length===allowed.length)}
function fees(show){var a=[],seen={},bad='';$('#fee_rows .fee-row').each(function(){var r=$(this),o=r.find('.fee-type option:selected'),id=+o.val()||0,code=String(o.data('code')||'').toLowerCase(),amount=r.find('.fee-amount').val(),targets=effectiveTargets(r);if(!id||seen[id]){bad='Select unique fee types.';return false}if(code!=='tuition'&&code!=='admission'&&(amount===''||+amount<0)){bad='Enter a valid amount for '+o.text()+'.';return false}if(!targets.length){bad='Select at least one student for '+o.text()+'.';return false}seen[id]=1;a.push({feetype_id:id,amount:amount===''?0:amount,student_session_ids:targets})});if(bad&&show)message('danger',bad);return bad?[]:a}
function payload(){var p=billing();p.fees=fees(1);p.students=[];p.operation_token=token;p.request_nonce=String(Date.now());$.each(students,function(_,s){p.students.push({selected:!!s.selected,student_session_id:+s.student_session_id,monthly_fee:s.monthly_fee,admission_fee:s.admission_fee,discount_fee:s.discount_fee,overrides:{}})});return p}
function submit(action){if(busy)return;var p=payload();if(!p.fees.length)return;if(!confirm(action==='generate'?'Generate only missing fees for each row\'s selected students? Existing fees will be skipped.':'Change due dates only for matching unpaid and undiscounted generated fees?'))return;setBusy(1);$.post(base+'admin/feemaster/'+(action==='generate'?'runGeneration':'updateGenerationFees'),{payload:JSON.stringify(p)},null,'json').done(function(r){var c=r.counts||{};message('success',action==='generate'?'Created '+(c.created||0)+'; already existed '+(c.existing||0)+'.':'Due dates changed '+(c.updated_fee_rows||0)+'; protected '+(c.locked||0)+'.',r.errors);loadStudents()}).fail(error).always(function(){setBusy(0)})}
function message(t,m,list){var h='<div class="alert alert-'+t+' alert-dismissible"><button class="close" data-dismiss="alert">&times;</button>'+esc(m);if(list&&list.length){h+='<ul>';$.each(list,function(_,x){h+='<li>'+esc(x)+'</li>'});h+='</ul>'}$('#fee_result').html(h+'</div>');window.scrollTo(0,0)}
function error(x){var r=x.responseJSON||{},e=r.errors||['The fee operation failed.'];message('danger',e[0],e.slice(1))}function setBusy(on){busy=!!on;$('#load_students,#add_fee,#generate_fees,#change_due_date,.remove-fee,.student-picker,#save_picker').prop('disabled',busy)}
$('#fee_class').on('change',loadSections);$('#load_students').on('click',loadStudents);$('#add_fee').on('click',function(){addRow('','')});$('#fee_rows').on('change','.fee-type',function(){amountState($(this).closest('.fee-row'))}).on('click','.remove-fee',function(){if($('#fee_rows .fee-row').length>1)$(this).closest('.fee-row').remove()}).on('click','.student-picker',function(){openPicker($(this).closest('.fee-row'))});
$('#student_table').on('change','.student-check',function(){var s=students[String($(this).closest('tr').data('id'))];if(s)s.selected=this.checked;render()});$('#select_all').on('change',function(){var on=this.checked;$.each(students,function(_,s){s.selected=s.eligible?on:false});render()});$('#student_search').on('input',render);
$('#picker_search').on('input',function(){renderPicker(pickerSelection,$.trim(this.value).toLowerCase())});$('#picker_list').on('change','.picker-check',function(){var id=+this.value;if(this.checked&&pickerSelection.indexOf(id)===-1)pickerSelection.push(id);if(!this.checked)pickerSelection=$.grep(pickerSelection,function(x){return x!==id})});$('#picker_all').on('change',function(){pickerSelection=this.checked?includedIds():[];renderPicker(pickerSelection,$.trim($('#picker_search').val()).toLowerCase())});$('#save_picker').on('click',function(){if(!pickerSelection.length)return;pickerRow.data('targets',pickerSelection.slice());refreshPickerLabel(pickerRow);$('#fee_students_modal').modal('hide')});$('#generate_fees').on('click',function(){submit('generate')});$('#change_due_date').on('click',function(){submit('due')});
var tuition=null;$.each(types,function(_,x){if(String(x.code).toLowerCase()==='tuition'&&!tuition)tuition=x});addRow(tuition?tuition.id:'','');
})(jQuery);
</script>
